package com.termux.app.workspace;
import android.view.*;import android.widget.*;import android.os.*;import android.app.AlertDialog;import android.text.*;import android.text.style.ForegroundColorSpan;import com.termux.app.TermuxActivity;import org.json.*;import java.util.*;import java.util.concurrent.*;import java.util.function.*;
/** Presentation only. The chat interface deliberately exposes no send/model operations. */
final class AgentProjectPanel implements AutoCloseable {
 interface Chat extends AutoCloseable{boolean valid();List<JSONObject> rows();boolean hasOlder();default boolean loadingOlder(){return false;}default String historyError(){return "";}void older();default boolean hasLongReferences(){return false;}default void moreReferences(){}default void retryRead(){if(hasLongReferences())moreReferences();else older();}void open(JSONObject file);boolean jump(String key);void observe(Runnable changed);void close();}
 interface Backend extends AutoCloseable{byte[] read(String script,int limit)throws Exception;void close();}
 final TermuxActivity activity;final WorkspaceStore.Session profile;final String directory;final Chat chat;final Backend backend;
 final Handler main=new Handler(Looper.getMainLooper());final ExecutorService work=Executors.newSingleThreadExecutor();
 final java.util.Map<String,String> availabilityCache=new java.util.HashMap<>();
 LinearLayout root,attachments,changes;FrameLayout content;View files;TextView[] tabs=new TextView[3];int selected,filter,referenceLimit=30;volatile int epoch;volatile boolean closed;java.util.function.Consumer<Boolean> fileVisibility;Consumer<String> navigate;ProjectChanges.Listing listing;
 AgentProjectPanel(TermuxActivity a,WorkspaceStore.Session p,String directory,Chat source){this(a,p,directory,source,new Backend(){final ProjectFiles fs=new ProjectFiles(a,p);public byte[] read(String s,int n)throws Exception{return fs.readOnly(s,n);}public void close(){fs.close();}});}
 AgentProjectPanel(TermuxActivity a,WorkspaceStore.Session p,String d,Chat c,Backend b){activity=a;profile=ChatAttachmentUi.source(p);directory=d;chat=c;backend=b;}
 String t(String ru,String en){return WorkspaceLanguage.code(activity).equals("ru")?ru:en;}
 String title(){return t("Файлы и изменения","Files and changes");}
 boolean owns(){return !closed&&chat.valid();}
 LinearLayout column(){LinearLayout v=new LinearLayout(activity);v.setOrientation(LinearLayout.VERTICAL);return v;}
 TextView label(LinearLayout parent,String text){TextView v=AgentStatusUi.info(parent,text);v.setTextIsSelectable(true);return v;}
 TextView action(LinearLayout parent,String text,Runnable click){TextView v=WorkspaceDialogs.action(activity,text,0);v.setOnClickListener(w->{if(owns())click.run();});parent.addView(v);return v;}
 View wrap(View fileView,Consumer<Boolean> visibility,Consumer<String> navigate){files=fileView;fileVisibility=visibility;this.navigate=navigate;root=column();root.setTag("agent-project-panel");label(root,AgentPreparation.agent(profile)+" · "+directory);
  LinearLayout row=new LinearLayout(activity);String[] names={t("Файлы","Files"),t("Вложения","Attachments"),t("Изменения","Changes")};for(int n=0;n<3;n++){final int index=n;tabs[n]=WorkspaceDialogs.action(activity,names[n],0);tabs[n].setTextSize(12);tabs[n].setTag("project-tab-"+n);tabs[n].setOnClickListener(v->{if(owns())select(index);});row.addView(tabs[n],new LinearLayout.LayoutParams(0,-2,1));}root.addView(row);
  content=new FrameLayout(activity);content.addView(files);attachments=column();changes=column();for(LinearLayout body:new LinearLayout[]{attachments,changes}){ScrollView scroll=new ScrollView(activity);scroll.addView(body);content.addView(scroll,new FrameLayout.LayoutParams(-1,-1));}root.addView(content,new LinearLayout.LayoutParams(-1,-2));chat.observe(()->{if(owns()&&selected==1)renderAttachments();});select(0);return root;
 }
 void select(int n){if(!owns())return;selected=n;epoch++;for(int i=0;i<3;i++){content.getChildAt(i).setVisibility(i==n?View.VISIBLE:View.GONE);tabs[i].setSelected(i==n);tabs[i].setTextColor(i==n?WorkspaceDialogs.ACCENT:WorkspaceDialogs.MUTED);}
  content.getLayoutParams().height=Math.max(WorkspaceDialogs.dp(activity,180),Math.min(WorkspaceDialogs.dp(activity,420),activity.getResources().getDisplayMetrics().heightPixels/2));content.requestLayout();fileVisibility.accept(n==0);if(n==1){availabilityCache.clear();renderAttachments();}if(n==2)loadChanges();
 }
 static String format(String name){int dot=name.lastIndexOf('.');return dot<0?"":name.substring(dot+1).toUpperCase(Locale.ROOT);}
 String date(long time){return time>0?new java.text.SimpleDateFormat("dd.MM.yyyy HH:mm:ss",Locale.getDefault()).format(new Date(time)):t("Дата неизвестна","Date unknown");}
 void renderAttachments(){if(!owns())return;final int token=++epoch;attachments.removeAllViews();LinearLayout filters=new LinearLayout(activity);String[] labels={t("Все","All"),t("От вас","From you"),t("От агента","From agent")};for(int i=0;i<3;i++){final int n=i;TextView b=WorkspaceDialogs.action(activity,labels[i],0);b.setTextSize(12);b.setTag("project-attachment-filter-"+i);b.setSelected(filter==i);b.setBackground(WorkspaceDialogs.background(activity,filter==i));b.setTextColor(filter==i?WorkspaceDialogs.ACCENT:WorkspaceDialogs.MUTED);b.setOnClickListener(v->{filter=n;renderAttachments();});filters.addView(b,new LinearLayout.LayoutParams(0,-2,1));}attachments.addView(filters);
  label(attachments,t("Из доступной истории адаптера текущего чата. Просмотр не отправляет файлы модели. Дата неизвестна, если CLI её не сообщает.","From the history this chat adapter makes available. Viewing does not send files to the model. Dates remain unknown when the CLI does not supply them."));
  if(!chat.historyError().isEmpty()){label(attachments,chat.historyError());TextView retry=action(attachments,t("Повторить","Retry"),chat::retryRead);retry.setEnabled(!chat.loadingOlder());}
  List<ChatFileReferences.Entry> refs=ChatFileReferences.collect(chat.rows());int shown=0;for(ChatFileReferences.Entry e:refs){if(filter==1&&!e.sender.equals("user")||filter==2&&!e.sender.equals("agent"))continue;if(shown++>=referenceLimit){action(attachments,t("Показать следующие вложения","Show more attachments"),()->{referenceLimit+=30;renderAttachments();});break;}JSONObject f=e.file;String path=f.optString("path",f.optString("url")),name=f.optString("name",new java.io.File(path).getName());LinearLayout card=column();card.setPadding(8,8,8,8);card.setBackground(WorkspaceDialogs.background(activity,false));attachments.addView(card);label(card,name);long bytes=f.optLong("bytes",-1);TextView metadata=label(card,format(name)+(bytes>=0?" · "+android.text.format.Formatter.formatFileSize(activity,bytes):t(" · размер неизвестен"," · size unknown"))+"\n"+date(e.time)+" · "+(e.sender.equals("user")?t("Вы","You"):AgentPreparation.agent(profile)));
   TextView availability=label(card,t("Доступность проверяется…","Checking availability…"));availability.setTag("project-file-availability");boolean local=path.startsWith("/")&&!path.startsWith("//");if(local&&availabilityCache.containsKey(path))availability.setText(availabilityCache.get(path));else if(local){work.execute(()->{if(closed||epoch!=token)return;String state;try{String p=ProjectFiles.target(path);byte[] value=backend.read("if [ -f "+p+" ] && [ -r "+p+" ]; then printf 'AVAILABLE ' ; stat -L -c '%s' -- "+p+"; else printf MISSING; fi",128);String info=new String(value,java.nio.charset.StandardCharsets.UTF_8).trim();state=info.startsWith("AVAILABLE")?t("Файл доступен","File available"):t("Файл недоступен; запись сохранена","File unavailable; record retained");if(info.startsWith("AVAILABLE "))try{long actual=Long.parseLong(info.substring(10));state+=" · "+android.text.format.Formatter.formatFileSize(activity,actual);}catch(Exception ignored){}}catch(Exception ex){state=t("Не удалось проверить доступность","Availability could not be checked");}final String result=state;main.post(()->{if(owns()&&epoch==token){availabilityCache.put(path,result);availability.setText(result);}});});}else availability.setText(t("Удалённый файл · не скачан","Remote file · not downloaded"));
   action(card,t("Открыть","Open"),()->{if(local)chat.open(f);else if(!safeRemote(path)){label(card,t("Этот удалённый адрес нельзя открыть","This remote address cannot be opened"));}else WorkspaceDialogs.builder(activity).setMessage(t("Удалённый файл не загружается автоматически.","Remote files are not downloaded automatically.")).setPositiveButton(t("Открыть ссылку","Open link"),(d,w)->{if(owns())try{activity.startActivity(new android.content.Intent(android.content.Intent.ACTION_VIEW,android.net.Uri.parse(path)));}catch(Exception ignored){}}).setNegativeButton(t("Отмена","Cancel"),null).show();});
   action(card,t("К сообщению","Go to message"),()->{if(chat.jump(e.key))dismiss.run();else label(card,t("Сообщение сейчас недоступно","Message currently unavailable"));});
   if(local)action(card,t("Показать расположение","Show location"),()->{select(0);navigate.accept(new java.io.File(path).getParent());});
  }if(shown==0&&chat.historyError().isEmpty())label(attachments,chat.hasOlder()||chat.hasLongReferences()||chat.loadingOlder()?t("В прочитанной части вложений не найдено. История ещё не прочитана полностью.","No attachments found in the portion read. History has not been fully read."):t("Вложений нет","No attachments"));if(chat.hasOlder()){TextView older=action(attachments,chat.loadingOlder()?t("Загрузка…","Loading…"):t("Загрузить ещё · история","Load more · history"),()->{chat.older();});older.setEnabled(!chat.loadingOlder());}if(chat.hasLongReferences()){TextView more=action(attachments,t("Загрузить ещё · полные сообщения","Load more · complete messages"),chat::moreReferences);more.setEnabled(!chat.loadingOlder());}action(attachments,t("Обновить","Refresh"),()->{availabilityCache.clear();renderAttachments();});
 }
 static boolean safeRemote(String url){try{android.net.Uri uri=android.net.Uri.parse(url);return java.util.Arrays.asList("https","http").contains(uri.getScheme())&&uri.getHost()!=null&&uri.getUserInfo()==null&&!url.matches(".*[\\s\\p{Cntrl}].*");}catch(Exception ignored){return false;}}
 Runnable dismiss=()->{};
 void loadChanges(){final int token=++epoch;changes.removeAllViews();label(changes,t("Чтение Git…","Reading Git…"));work.execute(()->{if(closed||epoch!=token)return;ProjectChanges.Listing value=null;Exception error=null;try{value=ProjectChanges.list(backend::read,directory);}catch(Exception ex){error=ex;}final ProjectChanges.Listing result=value;final Exception failure=error;main.post(()->{if(!owns()||epoch!=token)return;listing=result;changes.removeAllViews();if(failure!=null){label(changes,t("Не удалось прочитать изменения Git. Проверьте каталог и доступ.","Could not read Git changes. Check the folder and access."));}else if(!result.state.equals("OK")){label(changes,result.state.equals("NO_GIT")?t("Git не установлен","Git is not installed"):result.state.equals("NO_HEAD")?t("В проекте ещё нет коммита HEAD","This project has no HEAD commit yet"):t("Выбранная папка не является Git-проектом","The selected folder is not a Git project"));}else{label(changes,result.root+"\n"+t("База: HEAD ","Base: HEAD ")+result.head+"\n"+t("Подготовленные и неподготовленные изменения всего проекта. Они могут принадлежать вам и другим чатам. Внешние фильтры Git отключены; сравнивается исходное содержимое.","Staged and unstaged changes across the project. They may belong to you and other chats. External Git filters are disabled; raw content is compared."));if(result.entries.isEmpty())label(changes,t("Изменений нет","No changes"));for(ProjectChanges.Entry entry:result.entries)action(changes,entry.code+" · "+entry.path,()->showDiff(result,entry));}action(changes,t("Обновить","Refresh"),this::loadChanges);});});}
 void showDiff(ProjectChanges.Listing l,ProjectChanges.Entry e){final int token=++epoch;changes.removeAllViews();action(changes,t("Назад к изменениям","Back to changes"),this::loadChanges);label(changes,e.path+"\nHEAD "+l.head);TextView body=label(changes,t("Чтение различий…","Reading diff…"));body.setTypeface(android.graphics.Typeface.MONOSPACE);work.execute(()->{if(closed||epoch!=token)return;String value;try{String diff=ProjectChanges.diff(backend::read,l,e);value=diff.startsWith("BINARY")?t("Бинарный файл · ","Binary file · ")+e.code:diff.startsWith("TEXT\n")?diff.substring(5):t("Различия недоступны","Diff unavailable");if(value.isEmpty())value=t("Итоговых различий с HEAD нет. Подготовленные и неподготовленные изменения могут компенсировать друг друга.","No net difference from HEAD. Staged and unstaged changes may cancel each other.");}catch(Exception ex){value=t("Не удалось прочитать различия: файл изменился, недоступен или превышен предел предпросмотра (256 КБ). Обновите список.","Could not read diff: the file changed, is unavailable, or exceeds the 256 KB preview limit. Refresh the list.");}final CharSequence styled=diffColors(value);main.post(()->{if(owns()&&epoch==token)body.setText(styled);});});}
 static CharSequence diffColors(String value){SpannableString out=new SpannableString(value);int start=0;for(String line:value.split("\n",-1)){if(line.startsWith("+")&&!line.startsWith("+++"))out.setSpan(new ForegroundColorSpan(0xff9fdfba),start,start+line.length(),0);if(line.startsWith("-")&&!line.startsWith("---"))out.setSpan(new ForegroundColorSpan(0xffefa9ae),start,start+line.length(),0);start+=line.length()+1;}return out;}
 public void close(){if(closed)return;closed=true;epoch++;chat.close();backend.close();work.shutdownNow();}
}
